def main():
    out = pathlib.Path(__file__).resolve().parents[1] / "mmstudio" / "locales"
    out.mkdir(exist_ok=True)
    seen = set()
    for row in T:
        assert len(row) == 1 + len(LANGS), row[0]
        assert row[0] not in seen, f"duplicate key: {row[0]}"
        seen.add(row[0])
    for i, code in enumerate(LANGS, start=1):
        data = {row[0]: row[i] for row in T}
        (out / f"{code}.json").write_text(json.dumps(data, ensure_ascii=False, indent=1), encoding="utf-8")
    print(f"{len(T)} strings x {len(LANGS)} languages -> {out}")


if __name__ == "__main__":
    main()
